import{z as o,x as s,o as A,c as d,q as e,j as l,D as a,d as t,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"偏好数据的配比与域覆盖","description":"","frontmatter":{"title":"偏好数据的配比与域覆盖","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rm-data-mix.md","filePath":"llm/rm-data-mix.md","lastUpdated":1791063341000}'),n={name:"llm/rm-data-mix.md"};function m(_,E,p,F,D,h){const B=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=e('<h1 id="偏好数据的配比与域覆盖" tabindex="-1">偏好数据的配比与域覆盖 <a class="header-anchor" href="#偏好数据的配比与域覆盖" aria-label="Permalink to &quot;偏好数据的配比与域覆盖&quot;">​</a></h1><div class="epigraph"><p>全局准确率是一个会撒谎的平均数：把每个域各自的下限钉住，比把总分再抬高一分重要。</p><footer>—— 据 Touvron 等 Llama 2 2023 的数据集构成与 InstructGPT 2022 的消融整理</footer></div><p><a href="/llm/rm-data-sources">上一课</a>把比较对分成人工、隐式、AI 反馈与自评四类源，并要求各源成池后再混。缺口立刻出现：混的时候各占多少？本课写配比与域覆盖。预训练侧的<a href="/llm/data-mixture-laws">配比定律与领域配比</a>用代理损失找配比，偏好数据没有等价的代理目标——RM 的「损失」就是下游策略的行为，这使配比更像验收问题而非拟合问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>配比失衡的失效不是均匀变差，而是结构性塌陷。安全比较与有用比较的判据相反：前者赢方常是拒答，后者赢方常是给全。Llama 2 干脆拆成两个 RM，因为单一标量装不下这对冲突。若一份 RM 的数据里安全对占九成，容量会被安全特征占满，有用性维度退化成噪声；反过来闲聊对淹代码对，RM 在代码域的比较准确率会跌回 0.5 附近——等于随机，而全局准确率可能仍漂漂亮亮地停在 0.7。不这么做会错在哪：上线后才发现代码域奖励接近随机，RL 在该域的梯度就是噪声放大器。</p><p><span class="marginnote">初学者容易看到全局 0.7 就放心；但比较任务里 0.5 就是抛硬币，代码域跌回 0.5 意味着 RM 在这个域的偏好排序完全是猜。结构性塌陷最隐蔽的地方恰恰是：塌陷被均值藏住了，全局数字一动不动。</span></p><p>覆盖面是配比的另一半。域要按什么切？实用口径是「损失会因它而异」的粒度：事实问答、写作、代码、数学、多轮状态跟踪、安全拒答、格式遵循。切太粗，塌陷的子域藏在均值里；切太细，每个桶的样本撑不起稳定估计。经验起点是十来个域，每个域留出独立验证对。</p><h3 id="配比的三个轴" tabindex="-1">配比的三个轴 <a class="header-anchor" href="#配比的三个轴" aria-label="Permalink to &quot;配比的三个轴&quot;">​</a></h3><p>来源轴：人工与 AI 反馈各占多少。人工对贵而准，AI 对便宜可扩；常见做法是以人工对定锚、AI 对补量，人工池的占比按各域一致率分级。域轴：上段十余域的份额，向真实流量分布靠拢，再对安全域加权重，因为安全塌陷的代价不对称。难度轴：容易对帮 RM 学判据，难对（分数接近、结构相似）撑开分辨边界，类似<a href="/llm/hard-negatives">难负例挖掘</a>的道理；全给容易对，RM 学会的是挑软柿子。</p>',9)),(A(),l(i,null,{default:a(()=>[r(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%9D%A5%E6%BA%90%E6%B1%A0%EF%BC%9A%E4%BA%BA%E5%B7%A5%20%2F%20AI%20%2F%20%E9%9A%90%E5%BC%8F%22%5D%20--%3E%20MIX%5B%22%E9%85%8D%E6%AF%94%E7%9F%A9%E9%98%B5%EF%BC%9A%E6%9D%A5%E6%BA%90%20%C3%97%20%E5%9F%9F%20%C3%97%20%E9%9A%BE%E5%BA%A6%22%5D%0A%20%20MIX%20--%3E%20TRAIN%5B%22%E8%AE%AD%E7%BB%83%20RM%22%5D%0A%20%20TRAIN%20--%3E%20EVAL%5B%22%E5%88%86%E5%9F%9F%E9%AA%8C%E8%AF%81%E5%87%86%E7%A1%AE%E7%8E%87%22%5D%0A%20%20EVAL%20--%3E%7C%E6%9F%90%E5%9F%9F%E4%BD%8E%E4%BA%8E%E4%B8%8B%E9%99%90%7C%20ADJ%5B%22%E8%B0%83%E4%BB%BD%E9%A2%9D%EF%BC%9A%E8%A1%A5%E5%AF%B9%E6%88%96%E5%8A%A0%E6%9D%83%E9%87%8D%22%5D%0A%20%20ADJ%20--%3E%20MIX%0A%20%20EVAL%20--%3E%7C%E5%85%A8%E9%83%A8%E8%BE%BE%E6%A0%87%7C%20FREEZE%5B%22%E9%92%89%E9%85%8D%E6%AF%94%E5%85%A5%E6%95%B0%E6%8D%AE%E5%8D%A1%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>操作流程：先钉验证集——每个域独立的持有对，比例固定、永不进训练；再设初始配比（可从流量分布出发）；训练后看分域准确率而不是全局值；任何域低于预设下限就补对或加权，重训；达标后把配比写进数据卡。若做加权， \\(\\mathcal{L}=\\sum_d \\lambda_d\\,\\mathbb{E}_{\\text{域 }d}[\\ell_{\\mathrm{BT}}]\\) ， \\(\\lambda_d\\) 按下限缺口调整。预训练的 <a href="/llm/doremi">DoReMi</a> 与 <a href="/llm/regmix">RegMix</a> 用小模型搜配比，偏好侧只能省着用：每次改动都要重训 RM，消融贵，所以改动要有假设、有记录，别做无方向网格搜索。</p><p><span class="marginnote">给个数量感：设 12 个域、每域留 500 对持有对，验证集共 6000 对。若某域只留 100 对，单次估计的标准误约 \\(\\sqrt{0.25/100}=0.05\\)，测出 0.55 还是 0.65 可能只是抽样波动，「这个域塌没塌」根本判不了——这正是正文说「切太细，桶里样本撑不起稳定估计」的数学含义。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>配比起作用的机制是梯度竞争：BT 损失下，梯度大小正比于当前分错的程度，长期占多数的域在参数里留下更深的分界面；RM 容量不足时，稀有域的特征被挤压。所以「补数据」之前先看容量：小 RM 撑不起太多域，与其全部 0.6，不如砍掉低价值域保住关键域的 0.75。另一个机制是锚污染：AI 反馈池若在所有域同比例灌注，裁判的固定偏差就在每个域留下同向残差——上一课说噪声不独立，配比的机制面是：偏差也不独立，加大份额会线性放大它。</p>',5)),(A(),l(i,null,{default:a(()=>[r(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%AE%AD%E7%BB%83%E6%89%B9%E6%AC%A1%EF%BC%9A%E5%AE%89%E5%85%A8%E5%AF%B9%2090%25%20%2F%20%E4%BB%A3%E7%A0%81%E5%AF%B9%2010%25%22%5D%20--%3E%20B%5B%22BT%20%E6%8D%9F%E5%A4%B1%EF%BC%9A%E6%A2%AF%E5%BA%A6%E6%AD%A3%E6%AF%94%E4%BA%8E%E5%88%86%E9%94%99%E7%A8%8B%E5%BA%A6%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%A4%9A%E6%95%B0%E5%9F%9F%EF%BC%9A%E5%8F%8D%E5%A4%8D%E8%A2%AB%E4%BF%AE%E6%AD%A3%EF%BC%8C%E5%88%86%E7%95%8C%E9%9D%A2%E8%B6%8A%E5%88%BB%E8%B6%8A%E6%B7%B1%22%5D%0A%20%20B%20--%3E%20D%5B%22%E5%B0%91%E6%95%B0%E5%9F%9F%EF%BC%9A%E5%81%B6%E8%A2%AB%E4%BF%AE%E6%AD%A3%E4%B8%80%E6%AC%A1%EF%BC%8C%E5%8F%88%E8%A2%AB%E5%A4%9A%E6%95%B0%E5%9F%9F%E6%8C%A4%E5%9B%9E%22%5D%0A%20%20C%20--%3E%20E%5B%22RM%20%E6%9C%89%E9%99%90%E5%AE%B9%E9%87%8F%E8%A2%AB%E5%AE%89%E5%85%A8%E7%89%B9%E5%BE%81%E5%8D%A0%E6%BB%A1%22%5D%0A%20%20D%20--%3E%20F%5B%22%E4%BB%A3%E7%A0%81%E5%9F%9F%E7%89%B9%E5%BE%81%E9%80%80%E5%8C%96%E4%B8%BA%E5%99%AA%E5%A3%B0%22%5D%0A%20%20E%20--%3E%20G%5B%22%E4%BB%A3%E7%A0%81%E5%9F%9F%E5%87%86%E7%A1%AE%E7%8E%87%E6%BB%91%E5%90%91%200.5%EF%BC%88%E9%9A%8F%E6%9C%BA%EF%BC%89%22%5D%0A%20%20F%20--%3E%20G%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p><span class="marginnote">把锚污染想象成一把刻度整体偏短的尺子：无论量衣服还是量门框，都朝同一边偏。加大 AI 反馈池份额，相当于用这把尺子多量几次——次数再多偏差也不会互相抵消，只会把同向误差复制得更结实。这解释了为什么「多灌数据」救不了有偏的裁判。</span></p><p><span class="marginnote">一个常用的自查：把全局准确率按域拆开重写为 \\(\\sum_d w_d a_d\\) 。若各域 \\(a_d\\) 在 0.52 与 0.9 之间大幅摆动，说明均值无意义；配比的验收对象是 \\(\\min_d a_d\\)，不是 \\(\\sum_d w_d a_d\\)。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>配比不是一次定死的常数：策略迭代后各域的失分点会移动，配比要跟着采集计划（本课程后段的主动采集课）滚动。分域下限也不能防所有失效——两个域各自达标，但交界处（安全与写作之间的「敏感话题怎么聊」）可能仍是空洞，交界覆盖要靠专门构造的对。最后，配比消融用的是分域准确率，这只证明 RM 在该域「分得对」，不证明按它优化策略会变好；这一步的失效留给偏置单元与过优化课，本课先在数据侧把地基钉平。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>配比有三个轴：来源、域、难度；失衡的典型失效是某域准确率塌回随机而全局均值不变。</li><li>验收看分域持有准确率，验收对象是各域下限，不是加权平均。</li><li>机制是梯度竞争与锚污染：多数域占容量，AI 池份额放大裁判的固定偏差。</li><li>配比随策略迭代滚动，改动要有假设、要写进数据卡。</li><li>出处：Touvron 等 Llama 2，2023；Ouyang 等 InstructGPT，2022；预训练配比方法见 DoReMi、RegMix 对照。</li></ul>',6))])}const c=o(n,[["render",m]]);export{u as __pageData,c as default};
